import{_ as a,o as s,c as i,a3 as t}from"./chunks/framework.DLTBzH1I.js";const m=JSON.parse('{"title":"The release model","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/release-model.md","filePath":"explanation/release-model.md"}'),r={name:"explanation/release-model.md"};function o(l,e,n,d,c,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="the-release-model" tabindex="-1">The release model <a class="header-anchor" href="#the-release-model" aria-label="Permalink to &quot;The release model&quot;">​</a></h1><p>Releases are <strong>tag-only</strong> — there is no crates.io publish and no GitHub Releases artifact. The <code>mimus</code> crates are lib-only engines behind <code>tamias-driver-mimus</code> (plus a compat <code>mimus</code> bin for source installs); the user-facing command is the tamias pack in <code>libraries/mimus</code>.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><p><code>scripts/release.sh</code> is an operator-run shim over <a href="https://9aia.com/tarsi/" target="_blank" rel="noreferrer"><code>tarsi-serve</code></a> — the org release plane (project ADR-0005). One call runs plan → changelog → bump → tag → push; <code>tarsi-serve release</code> is dry-run by default and the script passes <code>--yes</code> as the explicit opt-in.</p><p>Repo policy lives in <code>tarsi.toml</code>:</p><ul><li><code>[publish.crates] enabled = false</code> — crates.io publishing is tamias-only (ADR-0004).</li><li><code>[publish.ghreleases] enabled = false</code> — org releases are tag-only; the capability stays for opt-in.</li><li><code>[release.sync_refs]</code> rewrites <code>libraries/mimus/tamias.yaml</code>&#39;s <code>version:</code> inside the release commit, so the tagged tree is self-consistent.</li></ul><p>Units default to cargo workspace members; versions are workspace-inherited, so releasing units share one bump.</p><p>One repo-specific step survives inside the shim: because docs drift with the CLI, the script regenerates <code>docs/reference/cli.md</code> and <code>docs/reference/config.md</code> via <code>cypera gen</code> <em>before</em> tagging (guarded — <code>docs/</code> is a separate worktree and absent in a detached release worktree).</p><h2 id="shipping-the-command" tabindex="-1">Shipping the command <a class="header-anchor" href="#shipping-the-command" aria-label="Permalink to &quot;Shipping the command&quot;">​</a></h2><p>Tagging doesn&#39;t publish anything user-facing. The pack ships manually:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">scripts/pack.sh</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                                # stage driver payload</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#   → release-builds tamias-driver-mimus into</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">#     libraries/mimus/drivers/bin/&lt;triple&gt;/ (gitignored)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tamias</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> publish</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> libraries/mimus</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # → 9aia:mimus@&lt;ver&gt;</span></span></code></pre></div><p>Install is then <code>tamias install 9aia:mimus@&lt;ver&gt;</code> (needs <code>TAMIAS_REGISTRY_TOKEN</code>) or <code>tamias install --allow-drivers ./libraries/mimus</code> from a checkout. <code>cargo install --git https://github.com/9aia/mimus mimus</code> remains the source path via the compat bin — pin a rev or tag.</p><h2 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h2><ul><li>There is no crates.io publish path and no per-crate tag scheme — the whole workspace shares one version. The old push-driven <code>mimus deploy release</code> seed (which <code>cargo publish</code>ed every member and uploaded cargo-dist binaries to a GitHub Release) is retired: org policy keeps every repo but tamias off crates.io, and prebuilt binary distribution is not part of the flow.</li></ul>`,14)])])}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
